# Also Object 0 (6x6) should be filled with fill_0=6, not 9!

def make_output(fill_0=6, fill_6=1, fill_3=1):
    result = [row[:] for row in test_input]

    # Object 0 (6x6, even size): fill = bg - 3 = 6
    # Interior: rows 3-6, cols 2-5
    for r in range(3, 7):
        for c in range(2, 6):
            if result[r][c] == 9:
                result[r][c] = fill_0  # 6

    # Object 6 (3x3, odd size): fill = bg + 2 = 1 (mod 10)
    # Interior: row 6, col 10
    for r in range(6, 7):
        for c in range(10, 11):
            if result[r][c] == 9:
                result[r][c] = fill_6  # 1

    # Object 3 (7x7, odd size): fill = bg + 2 = 1 (mod 10)
    # Interior: rows 2-6, cols 15-19
    for r in range(2, 7):
        for c in range(15, 20):
            if result[r][c] == 9:
                result[r][c] = fill_3  # 1

    return result

output = make_output(fill_0=6, fill_6=1, fill_3=1)

